function summary=runV4Stage3SSmoke(roundNumber)
root=v4SetupPaths();c=sf12NoLdroSf11FlowConfig();manifestPath=fullfile(root,'config',sprintf('paperReceiverParameterManifest_stage3s_v%02d.json',roundNumber));m=jsondecode(fileread(manifestPath));if ~strcmp(m.status,'safety-passed'),error('V4:Stage3SSmokeState','Expected safety-passed manifest.');end
seed=jsondecode(fileread(fullfile(root,'config','seed_protocol_r5_stage3s.json')));base=seed.domains.a_3s_smoke_v1;cases=[-366 0];records=cell(32,1);row=0;runtime=zeros(32,4);peakMemory=0;ticId=tic;
for ci=1:2,for packetId=1:16,row=row+1;records{row}=v4RunTrackAStage3SPairedPacket(c,cases(ci),-21,packetId,base+100000*ci,m.parameters);runtime(row,:)=records{row}.runtimeSec;try,mem=memory;peakMemory=max(peakMemory,mem.MemUsedMATLAB);catch,end;end,end
wall=toc(ticId);folder=fullfile(root,'results','stage3s','Stage55-A-point-anchored-provisional-lock-v2',m.parameterVersion,'smoke');if ~isfolder(folder),mkdir(folder);end
q=v4GenerateTrackAPacket(c,0,-21,999,base+900000);one=v4TrackAStage55PointAnchoredDecode(q,c,m.parameters);partial=v4TrackAStage55PointAnchoredDecode(q,c,m.parameters,StopAfterPhysicalRow=q.schedule.dataRows(1));checkpoint=fullfile(folder,'stage3s_smoke_checkpoint.mat');sig=[m.algorithmSignature '|smoke-resume'];v4WriteCheckpointAtomic(checkpoint,partial.checkpointState,sig);state=v4LoadCheckpoint(checkpoint,sig);resumed=v4TrackAStage55PointAnchoredDecode(q,c,m.parameters,ResumeState=state);resumePassed=isequaln(one.detectedPhysicalBins,resumed.detectedPhysicalBins)&&isequaln(one.virtualPilotAccepted,resumed.virtualPilotAccepted)&&strcmp(one.finalLockState,resumed.finalLockState);
summary=struct('status',ternary(resumePassed,'PASS','FAIL'),'parameterVersion',m.parameterVersion,'algorithmSignature',m.algorithmSignature,'seedDomain','a_3s_smoke_v1','packetCount',32,'wallSec',wall,'meanWallSecPerPacket',wall/32,'runtimeSec',runtime,'p95ReceiverRuntimeSec',prctile(runtime(:),95),'deadlineSec',c.symbolDurationSec,'deadlineMissCount',sum(runtime(:)>c.symbolDurationSec),'peakMatlabMemoryBytes',peakMemory,'checkpointResumePassed',resumePassed,'records',{records});
save(fullfile(folder,'stage3s_smoke.mat'),'summary','-v7.3');jsonSummary=rmfield(summary,'records');jsonPath=fullfile(folder,'stage3s_smoke.json');write(jsonPath,jsonencode(jsonSummary,'PrettyPrint',true));info=dir(fullfile(folder,'stage3s_smoke.mat'));estimate=struct('smokePackets',32,'formalPackets',400000,'meanWallSecPerPacket',wall/32,'conservativeRuntimeHours',1.25*(wall/32)*400000/3600,'smokeMatBytes',info.bytes,'conservativeStorageGiB',1.25*(info.bytes/32)*400000/2^30,'peakMatlabMemoryBytes',peakMemory);
reportFolder=fullfile(root,'results','stage3s','reports');if ~isfolder(reportFolder),mkdir(reportFolder);end;write(fullfile(reportFolder,'RUN_COST_ESTIMATE_A_R5.json'),jsonencode(estimate,'PrettyPrint',true));write(fullfile(reportFolder,'RUN_COST_ESTIMATE_A_R5.md'),sprintf('# Track A R5 run cost estimate\n\n- Conservative runtime: %.3f hours\n- Conservative storage: %.3f GiB\n- Fixed formal budget: 400000 paired packets.\n',estimate.conservativeRuntimeHours,estimate.conservativeStorageGiB));
if resumePassed,m.status='frozen-stage3s';m.smokeArtifactHash=v4Sha256(jsonPath);write(manifestPath,jsonencode(m,'PrettyPrint',true));else,error('V4:Stage3SSmoke','Smoke resume failed.');end
end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear c,end
